from collections import deque

def escape(rows, cols, walls, start, end):
    start, end = tuple(start), tuple(end)      # 输入可能是 list，统一成可哈希的 tuple
    blocked = set(map(tuple, walls))
    if start in blocked or end in blocked:
        return []
    parent = {start: None}
    q = deque([start])
    while q:
        cur = q.popleft()
        if cur == end:
            path = []
            while cur is not None:
                path.append(cur)
                cur = parent[cur]
            return path[::-1]
        r, c = cur
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            nxt = (nr, nc)
            if 0 <= nr < rows and 0 <= nc < cols and nxt not in blocked and nxt not in parent:
                parent[nxt] = cur
                q.append(nxt)
    return []
